// adds a new element to the set if space available

method add(v:int)
  requires RepInv()
  requires size() < maxSize()
  ensures RepInv()
  modifies this,Repr
  ensures fresh(Repr - old(Repr))
{
  if(v > 0) {
    var f:int := find(v);
    if (f < 0) {
      store[nelems] := v;
      elems := elems + {v};
      assert forall i:: 0 <= i < nelems ==> old(store[i]) == store[i];
      nelems := nelems + 1;
    }
